-- Additive free-tier workflow storage. Never deletes existing business records.
CREATE TABLE BusinessControl(businessId TEXT PRIMARY KEY REFERENCES Business(id),closedThrough TEXT,reason TEXT,updatedBy TEXT,updatedAt TEXT);
CREATE TABLE BusinessHistory(id INTEGER PRIMARY KEY AUTOINCREMENT,businessId TEXT NOT NULL,entityType TEXT NOT NULL,entityId TEXT NOT NULL,action TEXT NOT NULL,userId TEXT,beforeJson TEXT,afterJson TEXT,createdAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX History_business_date ON BusinessHistory(businessId,createdAt);
CREATE TRIGGER history_immutable_update BEFORE UPDATE ON BusinessHistory BEGIN SELECT RAISE(ABORT,'IMMUTABLE_HISTORY'); END;
CREATE TRIGGER history_immutable_delete BEFORE DELETE ON BusinessHistory BEGIN SELECT RAISE(ABORT,'IMMUTABLE_HISTORY'); END;
CREATE TABLE BusinessReview(id TEXT PRIMARY KEY,businessId TEXT NOT NULL REFERENCES Business(id),entityType TEXT NOT NULL,entityId TEXT NOT NULL,message TEXT NOT NULL,status TEXT NOT NULL,userId TEXT NOT NULL REFERENCES User(id),createdAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updatedAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX Review_business_date ON BusinessReview(businessId,createdAt);
CREATE TABLE BusinessEvidence(id TEXT PRIMARY KEY,businessId TEXT NOT NULL REFERENCES Business(id),entryId TEXT REFERENCES JournalEntry(id) ON DELETE SET NULL,invoiceId TEXT REFERENCES Invoice(id) ON DELETE SET NULL,fileName TEXT NOT NULL,mimeType TEXT NOT NULL,size INTEGER NOT NULL,digest TEXT NOT NULL,bytesBase64 TEXT NOT NULL,createdBy TEXT NOT NULL REFERENCES User(id),deletedAt TEXT,createdAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX Evidence_business_date ON BusinessEvidence(businessId,createdAt);
CREATE UNIQUE INDEX Evidence_unique_digest ON BusinessEvidence(businessId,digest) WHERE deletedAt IS NULL;
CREATE TRIGGER evidence_count_quota BEFORE INSERT ON BusinessEvidence WHEN (SELECT count(*) FROM BusinessEvidence WHERE businessId=NEW.businessId)>=100 OR (SELECT count(*) FROM BusinessEvidence)>=1000 BEGIN SELECT RAISE(ABORT,'EVIDENCE_QUOTA'); END;
CREATE TABLE WorkflowBudget(name TEXT PRIMARY KEY,bytes INTEGER NOT NULL,rows INTEGER NOT NULL);
INSERT INTO WorkflowBudget(name,bytes,rows) VALUES ('history',0,0);
CREATE TRIGGER history_quota BEFORE INSERT ON BusinessHistory WHEN (SELECT bytes+coalesce(length(NEW.beforeJson),0)+coalesce(length(NEW.afterJson),0)+300>52428800 OR rows>=50000 FROM WorkflowBudget WHERE name='history') BEGIN SELECT RAISE(ABORT,'WORKFLOW_QUOTA'); END;
CREATE TRIGGER history_budget AFTER INSERT ON BusinessHistory BEGIN UPDATE WorkflowBudget SET bytes=bytes+coalesce(length(NEW.beforeJson),0)+coalesce(length(NEW.afterJson),0)+300,rows=rows+1 WHERE name='history'; END;
CREATE UNIQUE INDEX One_sample_per_business ON JournalEntry(businessId) WHERE description='【サンプル】現金売上（実取引ではありません）';
CREATE TRIGGER evidence_quota BEFORE INSERT ON BusinessEvidence WHEN NEW.size>262144 OR NEW.size<1 OR (SELECT coalesce(sum(size),0) FROM BusinessEvidence WHERE businessId=NEW.businessId)+NEW.size>5242880 OR (SELECT coalesce(sum(size),0) FROM BusinessEvidence)+NEW.size>52428800 BEGIN SELECT RAISE(ABORT,'EVIDENCE_QUOTA'); END;
CREATE TABLE BusinessRecurring(id TEXT PRIMARY KEY,businessId TEXT NOT NULL REFERENCES Business(id),kind TEXT NOT NULL,sourceId TEXT NOT NULL,name TEXT NOT NULL,dayOfMonth INTEGER NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,createdBy TEXT NOT NULL,createdAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX Recurring_business ON BusinessRecurring(businessId,enabled);
CREATE TRIGGER recurring_quota BEFORE INSERT ON BusinessRecurring WHEN (SELECT count(*) FROM BusinessRecurring WHERE businessId=NEW.businessId AND enabled=1)>=20 BEGIN SELECT RAISE(ABORT,'WORKFLOW_QUOTA'); END;
CREATE TABLE BusinessRecurringRun(recurringId TEXT NOT NULL REFERENCES BusinessRecurring(id),month TEXT NOT NULL,targetId TEXT NOT NULL,createdAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(recurringId,month));
CREATE TRIGGER lock_JournalEntry_INSERT BEFORE INSERT ON JournalEntry WHEN EXISTS(SELECT 1 FROM BusinessControl WHERE businessId=NEW.businessId AND closedThrough IS NOT NULL AND date(NEW.entryDate)<=closedThrough) BEGIN SELECT RAISE(ABORT,'PERIOD_LOCKED'); END;
